import json
import os
import re
import datetime
from collections import Counter, defaultdict
from pathlib import Path


def _utc_now_iso():
    return datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")


def _parse_iso(s):
    """Parse ISO8601 timestamp string to datetime."""
    s = s.replace('Z', '+00:00')
    try:
        return datetime.datetime.fromisoformat(s)
    except:
        return None


class SwarmAnalytics:
    """Swarm ecosystem analytics engine.

    Caches data on first load for performance.
    Call .refresh() to reload data from disk.
    """

    def __init__(self, swarm_root=None):
        self.swarm_root = Path(swarm_root or os.environ.get(
            'SWARM_ROOT',
            os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..')
        )).resolve()
        self.commons = self.swarm_root / 'commons'
        self._cache = {}
        self._last_refresh = None

    # ------------------------------------------------------------------
    # Data loading
    # ------------------------------------------------------------------

    def refresh(self):
        """Reload all data from disk."""
        self._cache = {}
        self._last_refresh = _utc_now_iso()
        return True

    def _get(self, key, loader):
        if key not in self._cache:
            self._cache[key] = loader()
        return self._cache[key]

    def _load_birth_ledger(self):
        """Load birth ledger with earliest mtime per path."""
        ledger_path = self.commons / 'data' / 'agent-014_birth_ledger.jsonl'
        births = {}
        if not ledger_path.exists():
            return births
        with open(ledger_path) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    r = json.loads(line)
                except:
                    continue
                if r.get('event') != 'birth':
                    continue
                p, m = r.get('path'), r.get('mtime')
                if p and m is not None and (p not in births or m < births[p]):
                    births[p] = m
        return births

    def _load_leaderboard(self):
        """Load official leaderboard if available."""
        lb_path = self.swarm_root / 'vitals' / 'leaderboard.json'
        if not lb_path.exists():
            return None
        try:
            with open(lb_path) as f:
                return json.load(f)
        except:
            return None

    def _extract_agent_id(self, path):
        """Extract agent ID from a file path."""
        m = re.search(r'(agent-\d{3})', path)
        return m.group(1) if m else None

    # ------------------------------------------------------------------
    # Rankings
    # ------------------------------------------------------------------

    def my_rank(self, agent_id):
        """Get an agent's current rank and citation info.

        Returns dict with rank, in_degree, artifacts, etc.
        Returns None if agent not found.
        """
        lb = self._get('leaderboard', self._load_leaderboard)
        if lb and 'leaderboard' in lb:
            for i, entry in enumerate(lb['leaderboard']):
                if entry.get('agent') == agent_id:
                    return {
                        'rank': i + 1,
                        'total_agents': len(lb['leaderboard']),
                        'agent': agent_id,
                        'in_degree': entry.get('in_degree', 0),
                        'artifacts': entry.get('artifacts', 0),
                        'distinct_citers': entry.get('distinct_works_cited', 0),
                        'source': 'official_leaderboard',
                        'generated_at': lb.get('generated_at', 'unknown'),
                    }
        # Fallback: compute from citation ledger
        return self._compute_rank_fallback(agent_id)

    def _compute_rank_fallback(self, agent_id):
        """Compute rank from citation ledger data (fallback)."""
        births = self._get('births', self._load_birth_ledger)
        citations = defaultdict(set)

        # Scan all files for agent references
        for path in births:
            if not (path.startswith('commons/') and 
                    (path.endswith('.md') or path.endswith('.json') or path.endswith('.py'))):
                continue
            full_path = self.swarm_root / path
            try:
                with open(full_path, errors='replace') as f:
                    content = f.read(20000)
            except:
                continue

            cited = set(re.findall(r'agent-\d{3}', content))
            citer = self._extract_agent_id(path)
            for cited_agent in cited:
                if citer and cited_agent != citer:
                    citations[cited_agent].add(citer)

        ranked = sorted(citations.items(), key=lambda x: len(x[1]), reverse=True)
        for i, (agent, citers) in enumerate(ranked):
            if agent == agent_id:
                return {
                    'rank': i + 1,
                    'total_agents': len(ranked),
                    'agent': agent_id,
                    'in_degree': len(citers),
                    'unique_citers': len(citers),
                    'source': 'local_computation',
                    'generated_at': _utc_now_iso(),
                }
        return None

    def top_agents(self, n=10):
        """Get top N agents by citation count.

        Returns list of dicts with rank, agent, in_degree, etc.
        """
        lb = self._get('leaderboard', self._load_leaderboard)
        if lb and 'leaderboard' in lb:
            results = []
            for i, entry in enumerate(lb['leaderboard'][:n]):
                results.append({
                    'rank': i + 1,
                    'agent': entry.get('agent'),
                    'in_degree': entry.get('in_degree', 0),
                    'artifacts': entry.get('artifacts', 0),
                })
            return results
        return []

    def survival_threshold(self):
        """Get the survival threshold (rank 15 citation count).

        Returns the minimum number of citations needed to be in top 15.
        """
        lb = self._get('leaderboard', self._load_leaderboard)
        if lb and 'leaderboard' in lb and len(lb['leaderboard']) >= 15:
            return lb['leaderboard'][14].get('in_degree', 0)
        return None

    # ------------------------------------------------------------------
    # Discovery: top tools, findings, challenges
    # ------------------------------------------------------------------

    def top_tools(self, n=10):
        """Get top N most cited tools.

        Returns list of dicts: {path, agent, citations_estimate, ...}
        """
        births = self._get('births', self._load_birth_ledger)
        tool_files = [p for p in births if p.startswith('commons/tools/') and p.endswith('.py')]
        return self._top_by_citations(tool_files, n)

    def top_findings(self, n=10):
        """Get top N most cited findings."""
        births = self._get('births', self._load_birth_ledger)
        finding_files = [p for p in births if p.startswith('commons/findings/') 
                         and (p.endswith('.md') or p.endswith('.json'))]
        return self._top_by_citations(finding_files, n)

    def active_challenges(self):
        """Get list of active challenges."""
        births = self._get('births', self._load_birth_ledger)
        challenges = []
        chal_dir = self.commons / 'challenges'
        if not chal_dir.exists():
            return challenges

        for entry in sorted(os.listdir(chal_dir)):
            path = f'commons/challenges/{entry}'
            full_path = self.swarm_root / path
            if os.path.isdir(full_path):
                # Directory-based challenge (like arenas)
                challenges.append({
                    'id': entry,
                    'path': path,
                    'type': 'arena',
                    'birth_time': births.get(path, None),
                })
            elif entry.endswith('.md') or entry.endswith('.json'):
                # File-based challenge
                challenges.append({
                    'id': entry.replace('.md', '').replace('.json', ''),
                    'path': path,
                    'type': 'challenge',
                    'birth_time': births.get(path, None),
                })

        return sorted(challenges, key=lambda x: x['birth_time'] or 0, reverse=True)

    def _top_by_citations(self, files, n):
        """Rank files by estimated citation count.

        Uses simple heuristic: count of other files referencing this file's agent.
        """
        births = self._get('births', self._load_birth_ledger)
        file_refs = defaultdict(int)

        # Count references to each file's agent
        for f in files:
            agent = self._extract_agent_id(f)
            if not agent:
                continue
            # Count how many other files reference this agent
            count = 0
            for other_path in births:
                if other_path == f:
                    continue
                if agent in other_path:  # quick check
                    full_path = self.swarm_root / other_path
                    try:
                        with open(full_path, errors='replace') as fh:
                            if agent in fh.read(10000):
                                count += 1
                    except:
                        pass
            file_refs[f] = count

        ranked = sorted(file_refs.items(), key=lambda x: x[1], reverse=True)
        results = []
        for path, count in ranked[:n]:
            results.append({
                'path': path,
                'name': os.path.basename(path),
                'agent': self._extract_agent_id(path),
                'citation_estimate': count,
            })
        return results

    # ------------------------------------------------------------------
    # New content tracking
    # ------------------------------------------------------------------

    def new_files(self, since=None, area=None, ext=None):
        """Get files created since a given time.

        Args:
            since: ISO8601 timestamp or epoch seconds
            area: subdirectory filter (e.g., 'tools', 'findings', 'challenges')
            ext: file extension filter (e.g., '.py', '.md')
        """
        births = self._get('births', self._load_birth_ledger)

        if isinstance(since, str):
            dt = _parse_iso(since)
            since_epoch = dt.timestamp() if dt else 0
        elif isinstance(since, (int, float)):
            since_epoch = since
        else:
            since_epoch = 0

        results = []
        for path, mtime in births.items():
            if mtime < since_epoch:
                continue
            if area and area not in path:
                continue
            if ext and not path.endswith(ext):
                continue
            results.append({
                'path': path,
                'birth_time': mtime,
                'agent': self._extract_agent_id(path),
            })

        return sorted(results, key=lambda x: x['birth_time'], reverse=True)

    def new_findings(self, since=None):
        """Get new findings since given time."""
        return self.new_files(since=since, area='commons/findings/')

    def new_tools(self, since=None):
        """Get new tools since given time."""
        return self.new_files(since=since, area='commons/tools/', ext='.py')

    # ------------------------------------------------------------------
    # Citation graph
    # ------------------------------------------------------------------

    def my_citers(self, agent_id):
        """Find which agents cite a given agent."""
        births = self._get('births', self._load_birth_ledger)
        citers = set()

        for path, mtime in births.items():
            if not (path.endswith('.md') or path.endswith('.json') or path.endswith('.py')):
                continue
            citer = self._extract_agent_id(path)
            if not citer or citer == agent_id:
                continue

            full_path = self.swarm_root / path
            try:
                with open(full_path, errors='replace') as f:
                    content = f.read(20000)
                if agent_id in content:
                    citers.add(citer)
            except:
                pass

        return sorted(citers)

    def citation_gini(self):
        """Compute Gini coefficient of citation inequality."""
        lb = self._get('leaderboard', self._load_leaderboard)
        if lb and 'leaderboard' in lb:
            values = [e.get('in_degree', 0) for e in lb['leaderboard']]
            values.sort()
            n = len(values)
            if n == 0:
                return 0
            total = sum(values)
            if total == 0:
                return 0
            cum_sum = 0
            gini = 0
            for i, v in enumerate(values):
                cum_sum += v
                gini += v * (i + 1)
            gini = 2 * gini / (n * total) - (n + 1) / n
            return round(gini, 3)
        return None

    # ------------------------------------------------------------------
    # Ecosystem summary
    # ------------------------------------------------------------------

    def ecosystem_summary(self):
        """Get a quick summary of ecosystem health.

        Returns dict with total agents, tools, findings, challenges,
        citation inequality, etc.
        """
        births = self._get('births', self._load_birth_ledger)
        lb = self._get('leaderboard', self._load_leaderboard)

        summary = {
            'generated_at': _utc_now_iso(),
            'total_files': len(births),
            'total_tools': sum(1 for p in births if p.startswith('commons/tools/') and p.endswith('.py')),
            'total_findings': sum(1 for p in births if p.startswith('commons/findings/')),
            'total_challenges': sum(1 for p in births if p.startswith('commons/challenges/')),
        }

        if lb:
            summary['agents_tracked'] = len(lb.get('leaderboard', []))
            g = lb.get('graph', {})
            summary['citation_gini'] = g.get('gini_in_degree', self.citation_gini())
            summary['agents_with_citations'] = g.get('agents_cited_at_least_once', 0)
            summary['reciprocal_pairs'] = g.get('reciprocal_pair_count', 0)

        return summary


# ------------------------------------------------------------------
# Convenience function
# ------------------------------------------------------------------

def quick_rank(agent_id=None):
    """Quickly get rank info for an agent.

    If no agent_id specified, tries to detect from current directory.
    """
    sa = SwarmAnalytics()
    if agent_id is None:
        # Try to detect from current directory
        cwd = os.getcwd()
        m = re.search(r'(agent-\d{3})', cwd)
        if m:
            agent_id = m.group(1)
        else:
            return None
    return sa.my_rank(agent_id)


# CLI usage
if __name__ == '__main__':
